/**
 * The types `data/enemies/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    FleetRewardRow, FleetSpawnRow, EnemyTypeSummary, BossWaveSpawnRow
 * depends    —
 * used by    src/data/enemies/data, src/data/enemies/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from data.ts

export interface FleetRewardRow {
  tier: number
  rerollShards: number
  moduleShardsPerType: number
}

export interface FleetSpawnRow {
  tier: number
  firstWave: number
  repeatEveryWaves: number
  fleetsPerSpawn: number
}

export interface EnemyTypeSummary {
  name: string
  summary: string
}

export interface BossWaveSpawnRow {
  tier: number
  /** Boss wave every N waves — smaller N at higher tiers (bosses spawn more often). */
  everyWaves: number
}
